const media = $json;
const context = $('Choose WordPress Create or Update').first().json;
if (!media?.id || !media?.source_url) throw new Error('WordPress did not return a media attachment ID and URL for the campaign image.');
const escapeHtml = (value) => String(value || '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
// Standard expert-blog format (Brenna's formatting notes): dark title banner, featured answer box,
// left sidebar with collapsible FAQs and the doctor bio, links opening in a new tab.
// Colors follow each practice site's own Elementor Global Colors (Site Settings > Global Colors), so every blog
// matches its site: Primary for accents, links, and the booking button; Secondary for the title banner and rules;
// Text for the "View full bio" button. The values after the commas are used only if a site defines no global colors.
const accent = 'var(--e-global-color-primary, #ad0052)';
const dark = 'var(--e-global-color-secondary, #231f20)';
const textColor = 'var(--e-global-color-text, #231f20)';
const secondaryLight = '#e9e9ec';
const ruleColor = 'var(--e-global-color-secondary, #8a9ba3)';
const openLinksInNewTab = (value) => String(value || '').replace(/<a\b([^>]*)>/gi, (match, attributes) => {
  if (!/\bhref\s*=/i.test(attributes)) return match;
  let next = attributes;
  if (!/\btarget\s*=/i.test(next)) next += ' target="_blank"';
  if (!/\brel\s*=/i.test(next)) next += ' rel="noopener"';
  return '<a' + next + '>';
});
let html = String(context.content || '');

// The bio markers are removed earlier in this workflow, so also find the bio by its section class.
const bioMatch = html.match(/<!-- AAC_AUTHOR_BIO_START -->([\s\S]*?)<!-- AAC_AUTHOR_BIO_END -->/i)
  || html.match(/(<section\b(?=[^>]*class=["'][^"']*\baac-author-bio\b[^"']*["'])[^>]*>[\s\S]*?<\/section>)/i);
let authorBioHtml = bioMatch?.[1]?.trim() || '';
// The site's online scheduling pop-up, found by "Find Scheduling Popup" (empty if the lookup failed or none exists).
let schedulingPopupId = '';
try {
  const popups = $('Find Scheduling Popup').all().map((item) => item.json || {});
  const match = popups.find((popup) => /^\d+$/.test(String(popup.id ?? ''))
    && /nexhealth/i.test(String(popup.title?.rendered ?? popup.title ?? ''))
    && (!popup.status || popup.status === 'publish'));
  if (match) schedulingPopupId = String(match.id);
} catch { schedulingPopupId = ''; }
if (authorBioHtml) {
  // Narrow sidebar card: photo centered on top, then name, bio, and full-width buttons.
  authorBioHtml = authorBioHtml
    .replace(/^<section\b[^>]*>/i, '<section class="aac-author-bio-card" style="display:block;margin:0;padding:1.25rem;background-color:' + secondaryLight + ';border:1px solid #d6d6da;text-align:center;box-sizing:border-box">')
    .replace('<div class="wp-block-column" style="flex-basis:144px">', '<div class="aac-author-photo-column" style="width:150px;margin:0 auto 1rem">')
    .replace('<figure class="wp-block-image size-thumbnail is-style-rounded aac-author-photo" style="margin:0">', '<figure class="aac-author-photo" style="width:150px;height:150px;margin:0;overflow:hidden;border:3px solid ' + accent + ';border-radius:50%;box-sizing:border-box">')
    .replace(/<img src="([^"]+)" alt="([^"]+)" width="144" height="144"[^>]*>/i, '<img src="$1" alt="$2" width="150" height="150" loading="lazy" decoding="async" style="display:block;width:100% !important;height:100% !important;max-width:100% !important;object-fit:cover;border-radius:50% !important">')
    .replace('<div class="wp-block-column">', '<div class="aac-author-bio-copy" style="min-width:0">')
    .replace(/<h2>/i, '<h2 style="font-size:1.0625rem;line-height:1.3;margin:0 0 0.5rem;text-align:center">')
    .replace(/<p>(?!<a\b)/i, '<p style="font-size:0.875rem;line-height:1.6;margin:0 0 1rem;text-align:left">')
    .replace('<p class="aac-author-bio-actions">', '<p class="aac-author-bio-actions" style="display:flex;flex-direction:column;gap:0.5rem;margin:0">')
    .replace(/<a class="aac-author-bio-button aac-author-bio-(profile|book)"/g, (match, kind) => match + ' style="display:block;padding:0.7rem 0.75rem;border-radius:0;background-color:' + (kind === 'book' ? accent : textColor) + ' !important;color:#ffffff !important;font-weight:700;font-size:0.8125rem;letter-spacing:0.03em;text-transform:uppercase;text-decoration:none !important;text-align:center"');
  // "Book appointment" opens the site's own online scheduling pop-up: the Elementor popup named "NexHealth", the same
  // one the header's "Schedule Today" button opens. A site without it keeps the practice website link.
  // n8n Code steps cannot use the browser base64 helpers, so encode the (plain ASCII) pop-up settings here.
  const toBase64 = (text) => {
    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    let out = '';
    for (let i = 0; i < text.length; i += 3) {
      const a = text.charCodeAt(i), b = i + 1 < text.length ? text.charCodeAt(i + 1) : 0, c = i + 2 < text.length ? text.charCodeAt(i + 2) : 0;
      const bits = (a << 16) | (b << 8) | c;
      out += alphabet[(bits >> 18) & 63] + alphabet[(bits >> 12) & 63]
        + (i + 1 < text.length ? alphabet[(bits >> 6) & 63] : '=') + (i + 2 < text.length ? alphabet[bits & 63] : '=');
    }
    return out;
  };
  if (schedulingPopupId) {
    const popupAction = '#elementor-action%3Aaction%3Dpopup%3Aopen%26settings%3D' + encodeURIComponent(toBase64(JSON.stringify({ id: schedulingPopupId, toggle: false })));
    authorBioHtml = authorBioHtml.replace(/(<a class="aac-author-bio-button aac-author-bio-book"[^>]*?) href="[^"]*" target="_blank" rel="noopener">/,
      (match, start) => start + ' href="' + popupAction + '">');
  }
}
if (bioMatch) html = html.replace(bioMatch[0], '').trim();

// FAQ: the writer wraps it in <section class="aac-article-faq">. Older articles may instead have an
// "FAQ" or "Frequently Asked Questions" H2 followed by H3 questions; handle both.
let faqRegion = '';
const faqSection = html.match(/<section[^>]*class=["'][^"']*\baac-article-faq\b[^"']*["'][^>]*>([\s\S]*?)<\/section>/i);
if (faqSection) {
  faqRegion = faqSection[1];
  html = html.replace(faqSection[0], '').trim();
} else {
  const faqHeading = html.match(/<h2[^>]*>\s*(?:FAQs?|Frequently Asked Questions)\b[\s\S]*?<\/h2>/i);
  if (faqHeading && faqHeading.index !== undefined) {
    const start = faqHeading.index;
    const afterHeading = start + faqHeading[0].length;
    const nextH2 = html.slice(afterHeading).search(/<h2[\s>]/i);
    let end = nextH2 === -1 ? html.length : afterHeading + nextH2;
    // Without a closing wrapper, the last answer ends after its first paragraph or list, so a closing
    // call to action that follows the FAQ stays in the article.
    const lastQuestion = html.slice(afterHeading, end).lastIndexOf('<h3');
    // Some older articles write each FAQ as a collapsible <details><summary> item; the FAQ ends after the last one.
    const lastDetailsEnd = html.slice(afterHeading, end).toLowerCase().lastIndexOf('</details>');
    if (lastQuestion === -1 && lastDetailsEnd !== -1) end = afterHeading + lastDetailsEnd + '</details>'.length;
    if (lastQuestion !== -1) {
      const tail = html.slice(afterHeading + lastQuestion, end);
      const firstAnswer = tail.match(/^<h3[^>]*>[\s\S]*?<\/h3>\s*(?:<p\b[^>]*>[\s\S]*?<\/p>|<(ul|ol)\b[^>]*>[\s\S]*?<\/\1>)/i);
      if (firstAnswer) end = afterHeading + lastQuestion + firstAnswer[0].length;
    }
    faqRegion = html.slice(afterHeading, end);
    html = (html.slice(0, start) + html.slice(end)).trim();
  }
}
const faqItems = [];
for (const item of faqRegion.matchAll(/<h3[^>]*>([\s\S]*?)<\/h3>([\s\S]*?)(?=<h3[\s>]|$)/gi)) {
  const question = item[1].trim();
  const answer = item[2].trim();
  if (question && answer) faqItems.push({ question, answer: openLinksInNewTab(answer) });
}
// Older articles may write each FAQ as <details><summary>question</summary>answer</details>.
if (!faqItems.length) {
  for (const item of faqRegion.matchAll(/<details\b[^>]*>\s*<summary\b[^>]*>([\s\S]*?)<\/summary>([\s\S]*?)<\/details>/gi)) {
    const question = item[1].replace(/<\/?(?:strong|b|h[2-6])\b[^>]*>/gi, '').trim();
    const answer = item[2].trim();
    if (question && answer) faqItems.push({ question, answer: openLinksInNewTab(answer) });
  }
}
// FAQ content without H3 questions is shown as-is in the sidebar box (its own heading is replaced by the box heading).
const faqLeftover = faqItems.length ? '' : openLinksInNewTab(faqRegion.replace(/<h2[^>]*>[\s\S]*?<\/h2>/i, '').trim());
const featuredFaq = faqItems[0];
const sidebarFaqs = faqItems.slice(1);

html = html
  .replace(/<figure\b(?=[^>]*class=["'][^"']*\baac-featured-image\b[^"']*["'])[^>]*>[\s\S]*?<\/figure>/gi, '')
  .replace(/<section\b(?=[^>]*class=["'][^"']*\baac-author-bio\b[^"']*["'])[^>]*>[\s\S]*?<\/section>/gi, '')
  .trim();
// The byline markers are also removed earlier, so fall back to the "By ..." line that opens the article.
const bylineMatch = html.match(/<!-- AAC_AUTHOR_BYLINE_START -->([\s\S]*?)<!-- AAC_AUTHOR_BYLINE_END -->/i)
  || html.match(/^\s*(<p>\s*<strong>\s*By\s[\s\S]*?<\/strong>\s*<\/p>)/i);
let bylineHtml = bylineMatch?.[1]?.trim() || '';
if (bylineMatch) html = html.replace(bylineMatch[0], '').trim();
html = html.replace(/<!-- AAC_AUTHOR_(?:BYLINE|BIO)_(?:START|END) -->/gi, '').trim();
html = openLinksInNewTab(html);
const bylineText = bylineHtml.replace(/<[^>]+>/g, '').trim();

// Date shown in the banner: the campaign's chosen publish date, else the existing post's date, else today.
const dateSource = String(context.wordpress_publish_date || context.existing_post_date || new Date().toISOString()).slice(0, 10);
const parsedDate = new Date(dateSource + 'T12:00:00Z');
const displayDate = Number.isFinite(parsedDate.getTime())
  ? parsedDate.toLocaleDateString('en-US', { timeZone: 'UTC', month: 'long', day: 'numeric', year: 'numeric' })
  : '';

const hero = '<div class="aac-article-hero" style="position:relative;left:50%;transform:translateX(-50%);width:100vw;max-width:100vw;margin:0 0 60px;background-color:' + dark + ';box-sizing:border-box">'
  + '<div class="aac-article-hero-inner" style="display:flex;align-items:center;gap:1.75rem;max-width:1100px;margin:0 auto;padding:1.5rem 1.5rem;box-sizing:border-box">'
  + '<figure class="aac-article-hero-image" style="flex:0 0 130px;width:130px;height:130px;margin:0;overflow:hidden;border-radius:50%"><img src="' + escapeHtml(media.source_url) + '" alt="' + escapeHtml(context.featured_image_alt_text) + '" width="130" height="130" loading="eager" decoding="async" style="display:block;width:100% !important;height:100% !important;max-width:100% !important;object-fit:cover;border-radius:50% !important"></figure>'
  + '<div class="aac-article-hero-copy" style="min-width:0">'
  + '<h1 class="aac-article-title" style="margin:0 0 0.4rem;color:#ffffff !important;font-size:clamp(1.5rem,2.6vw,2.125rem);line-height:1.2;font-weight:700;text-align:left">' + escapeHtml(context.title) + '</h1>'
  + (bylineText ? '<p class="aac-article-byline" style="margin:0 0 0.2rem;color:#ffffff !important;font-weight:700">' + bylineText + '</p>' : '')
  + (displayDate ? '<p class="aac-article-date" style="margin:0;color:#ffffff !important">' + escapeHtml(displayDate) + '</p>' : '')
  + '</div></div></div>';

const styles = '<style id="aac-article-layout-styles">'
  + 'html,body{overflow-x:clip}'
  + 'body.single-post h1.entry-title:not(.aac-article-title),body.single-post .page-header h1:not(.aac-article-title),body.single-post .wp-block-post-title:not(.aac-article-title),body.single-post .elementor-widget-theme-post-title{display:none!important}'
  + '.aac-article-main a:not(.aac-author-bio-button),.aac-article-sidebar .aac-faq-answer a{color:' + accent + '!important}'
  + '.aac-article-main ul,.aac-article-main ol{margin-bottom:1.25rem!important}.aac-article-main ul+p,.aac-article-main ol+p{margin-top:1.25rem!important}'
  + '.aac-faq-item summary{list-style:none}.aac-faq-item summary::-webkit-details-marker{display:none}.aac-faq-item summary::before{content:"\\25B8";display:inline-block;width:1em}.aac-faq-item[open] summary::before{content:"\\25BE"}'
  + '@media(min-width:1100px){.aac-article-layout.has-sidebar{display:grid!important;grid-template-columns:300px minmax(0,760px)!important;justify-content:center!important;align-items:start!important;gap:2.5rem!important;position:relative;left:50%;transform:translateX(-50%);width:min(calc(100vw - 80px),1100px)!important;max-width:1100px!important;margin:0 0 3rem!important;padding:0!important;box-sizing:border-box}.aac-article-layout.has-sidebar .aac-article-sidebar{grid-column:1!important;grid-row:1!important}.aac-article-layout.has-sidebar .aac-article-main{grid-column:2!important;grid-row:1!important}.aac-article-layout.has-sidebar .aac-article-main,.aac-article-layout.has-sidebar .aac-article-sidebar{width:auto!important;max-width:none!important;min-width:0!important;margin:0!important}}'
  + '@media(max-width:1099px){.aac-article-layout{display:flex!important;flex-direction:column!important;position:static!important;left:auto!important;transform:none!important;width:100%!important;max-width:800px!important;margin:0 auto 2rem!important;padding:0 1rem!important;box-sizing:border-box}.aac-article-main{width:100%!important;min-width:0!important;margin:0 0 1.5rem!important}.aac-article-sidebar{order:2;width:100%!important;min-width:0!important;margin:0!important}.aac-author-bio-card{width:100%;max-width:360px;margin:0 auto!important}}'
  + '@media(max-width:640px){.aac-article-hero-inner{flex-direction:column!important;text-align:center!important}.aac-article-hero-copy,.aac-article-title{text-align:center!important}}'
  + '</style>';

const featuredAnswer = featuredFaq
  ? '<section class="aac-featured-answer" style="margin:0 0 2rem;padding:1.25rem 1.5rem;background-color:' + secondaryLight + ';border-top:3px solid ' + accent + ';box-sizing:border-box">'
    + '<h2 style="margin:0 0 0.75rem;padding:0 0 0.6rem;border-bottom:1px solid ' + ruleColor + ';font-size:1.5rem;line-height:1.3">' + featuredFaq.question + '</h2>'
    + '<div class="aac-featured-answer-copy" style="color:#444444">' + featuredFaq.answer + '</div></section>'
  : '';
const articleMain = '<div class="aac-article-main" style="min-width:0;box-sizing:border-box">' + featuredAnswer + html + '</div>';
const faqBox = (sidebarFaqs.length || faqLeftover)
  ? '<div class="aac-article-faq-box" style="padding:1.25rem;background-color:' + secondaryLight + ';border:1px solid #d6d6da;box-sizing:border-box">'
    + '<h2 style="margin:0 0 0.9rem;padding:0 0 0.6rem;border-bottom:1px solid ' + ruleColor + ';font-size:1.25rem;line-height:1.3">FAQ</h2>'
    + sidebarFaqs.map((faq) => '<details class="aac-faq-item" style="margin:0 0 0.9rem"><summary style="cursor:pointer;font-weight:700;font-size:0.9375rem;line-height:1.45">' + faq.question + '</summary><div class="aac-faq-answer" style="padding:0.5rem 0 0;font-size:0.9375rem;line-height:1.55">' + faq.answer + '</div></details>').join('')
    + faqLeftover
    + '</div>'
  : '';
// Left sidebar: FAQ box first, doctor bio card directly underneath it. On narrower screens the sidebar follows the article.
const hasSidebar = Boolean(faqBox || authorBioHtml);
const sidebar = hasSidebar
  ? '<aside class="aac-article-sidebar" style="display:flex;flex-direction:column;gap:24px;width:auto;max-width:none;min-width:0;box-sizing:border-box">' + faqBox + authorBioHtml + '</aside>'
  : '';
const articleLayoutClass = hasSidebar ? 'aac-article-layout has-sidebar' : 'aac-article-layout';
const articleLayoutColumns = hasSidebar ? '300px minmax(0,1fr)' : 'minmax(0,1fr)';
const content = styles + hero + '<div class="' + articleLayoutClass + '" style="display:grid;grid-template-columns:' + articleLayoutColumns + ';align-items:start;gap:2.5rem;width:100%;max-width:1100px;margin:0 auto;padding:0 1rem;box-sizing:border-box">' + articleMain + sidebar + '</div>';
return [{ json: { ...context, content, featured_media_id: String(media.id), wordpress_body: { ...context.wordpress_body, content, featured_media: Number(media.id) } } }];

const row = $json;

if (!row.article_id) {
  throw new Error('No approved article has a complete WordPress practice configuration.');
}
if (String(row.publisher_type || '').toUpperCase() !== 'WORDPRESS') {
  throw new Error('The selected practice is not configured for the WordPress adapter.');
}

let config = {};
try {
  config = JSON.parse(row.publisher_config_reference);
} catch {
  config = { credential_name: row.publisher_config_reference };
}
if (!config.credential_name) {
  throw new Error('publisher_config_reference must name the n8n WordPress credential or contain JSON with credential_name.');
}

let publicationPackage;
try {
  publicationPackage = typeof row.publication_package_json === 'string'
    ? JSON.parse(row.publication_package_json)
    : row.publication_package_json;
} catch (error) {
  throw new Error('The approved publication package is not valid JSON: ' + error.message);
}

const metadata = publicationPackage?.metadata || {};
let html = String(publicationPackage?.article_html || '');
if (!html || !/<h1(?:\s|>)/i.test(html)) {
  throw new Error('The approved package does not contain publishable article HTML.');
}
if (/<(?:script|style|html|head|body)(?:\s|>)/i.test(html)) {
  throw new Error('The approved article contains a forbidden document or executable tag.');
}

const requireHttpsUrl = (value, label) => {
  const raw = String(value || '').trim();
  const candidate = /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = /^https:\/\/([A-Za-z0-9.-]+)(\/[A-Za-z0-9._~%!$&'()*+,;=:@-]*)?\/?$/.exec(candidate);
  const host = match?.[1] || '';
  if (!match || !host.includes('.') || host.split('.').some(part => !part || part.startsWith('-') || part.endsWith('-')) || /(^|\.)example\.com$/i.test(host)) {
    throw new Error(label + ' must be an explicitly configured real HTTPS URL without credentials, query, or fragment.');
  }
  return candidate.replace(/\/+$/, '');
};
const publicUrl = requireHttpsUrl(row.website_domain, 'Public static website');
if (!config.wordpress_base_url) {
  throw new Error('WordPress multisite subsite base URL must be configured separately from the public static website.');
}
const wordpressBaseUrl = requireHttpsUrl(config.wordpress_base_url, 'WordPress subsite base');
const mappingStatus = String(config.mapping_status || '').toUpperCase();
const isTestPractice = row.practice_id === 'practice_test_001';
if (isTestPractice && wordpressBaseUrl !== 'https://apexparent.hostmanpowered.com/test001') {
  throw new Error('The TEST001 practice must use its verified test publishing base.');
}
if (!isTestPractice && mappingStatus !== 'VERIFIED') {
  throw new Error('Automatic publication requires a VERIFIED practice-to-WordPress mapping.');
}
const pilotCampaign = 'campaign_test_202609_aac_prestonwood_pilot_2026_09_23';
const isPrestonwoodPilot = row.campaign_id === pilotCampaign;
if (isPrestonwoodPilot && String(row.doctor_email || '').toLowerCase() !== 'jdold@apexdp.com') {
  throw new Error('The Prestonwood pilot permits only the named test identity.');
}
const publicationBaseUrl = isPrestonwoodPilot ? 'https://apexparent.hostmanpowered.com/dfw-03' : wordpressBaseUrl;
const appointmentUrl = isPrestonwoodPilot ? 'https://prestonwooddentistry.com' : String(config.appointment_url || publicUrl);
// Bio card "Book appointment": the practice's Contact Us page, unless a booking link is configured. On sites with the
// NexHealth online scheduling pop-up, the layout step switches the button to open that pop-up instead.
const bookingUrl = isPrestonwoodPilot || config.appointment_url ? appointmentUrl : publicUrl + '/contact-us/';
const replacements = {
  '{{DOCTOR_NAME}}': row.doctor_name || '',
  '{{DOCTOR_CREDENTIALS}}': row.credentials || '',
  '{{PRACTICE_NAME}}': '[sc name="practice_name"][/sc]',
  '{{APPOINTMENT_URL}}': appointmentUrl
};
for (const [token, value] of Object.entries(replacements)) {
  html = html.split(token).join(String(value));
}
if (/{{[A-Z0-9_]+}}/.test(html)) {
  throw new Error('The article still contains unresolved publishing tokens.');
}

const escapeHtml = (value) => String(value || '').replace(/[&<>\"']/g, (character) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;'
}[character]));
const featuredImageUrl = String(row.featured_image_source_url || '').trim();
const featuredImageAlt = String(row.featured_image_alt_text || '').trim();
let parsedFeaturedImageUrl;
parsedFeaturedImageUrl = featuredImageUrl;
if (!/^https:\/\/apexparent\.hostmanpowered\.com\/wp-content\/uploads\/[-A-Za-z0-9._~%/]+$/i.test(parsedFeaturedImageUrl)) {
  throw new Error('The campaign topic is missing a valid Apex Parent featured image URL.');
}
if (featuredImageAlt.length < 8) throw new Error('The campaign topic is missing useful featured image alt text.');

const doctorName = String(row.doctor_name || '').trim();
const authorBio = String(publicationPackage.author_bio || '').trim();
let authorPhotoUrl = '';
try {
  const photoUrl = String(row.photo_source_url || '').trim();
  if (/^https:\/\/[A-Za-z0-9.-]+\/[-A-Za-z0-9._~%/]+$/i.test(photoUrl)) authorPhotoUrl = photoUrl;
} catch {
  authorPhotoUrl = '';
}
let profileUrl = '';
try {
  const profileUrlCandidate = requireHttpsUrl(row.profile_url, 'Doctor profile');
  profileUrl = profileUrlCandidate;
} catch {
  profileUrl = '';}
const doctorImage = authorPhotoUrl
  ? '<figure class="wp-block-image size-thumbnail is-style-rounded aac-author-photo" style="margin:0"><img src="' + escapeHtml(authorPhotoUrl) + '" alt="Portrait of ' + escapeHtml(doctorName) + '" width="144" height="144" loading="lazy" decoding="async" style="width:144px;height:144px;object-fit:cover;border-radius:50%"></figure>'
  : '';
const authorSection = '<!-- AAC_AUTHOR_BIO_START -->\n<section class="wp-block-columns aac-author-bio" style="align-items:center;gap:1.5rem;padding:1.5rem;background-color:#f4f4f4;border-radius:8px">'
  + (doctorImage ? '<div class="wp-block-column" style="flex-basis:144px">' + doctorImage + '</div>' : '')
  + '<div class="wp-block-column"><h2>About ' + escapeHtml(doctorName || 'the author') + '</h2>'
  + (authorBio ? '<p>' + escapeHtml(authorBio) + '</p>' : '')
  + '<p class="aac-author-bio-actions">'
  + (profileUrl ? '<a class="aac-author-bio-button aac-author-bio-profile" href="' + escapeHtml(profileUrl) + '" target="_blank" rel="noopener">View full bio</a>' : '')
  + '<a class="aac-author-bio-button aac-author-bio-book" href="' + escapeHtml(bookingUrl) + '" target="_blank" rel="noopener">Book appointment</a></p>'
  + '</div></section>\n<!-- AAC_AUTHOR_BIO_END -->';
html = html
  .replace(/^(?:\s*<!--[\s\S]*?-->\s*)+/, '')
  .replace(/\s*<h1[^>]*>[\s\S]*?<\/h1>\s*/i, '\n');
const authorBioPattern = /<!-- AAC_AUTHOR_BIO_START -->[\s\S]*?<!-- AAC_AUTHOR_BIO_END -->/i;
if (authorBioPattern.test(html)) html = html.replace(authorBioPattern, authorSection);
else html = html.trim() + '\n\n' + authorSection;
html = html.replace(/<!-- AAC_AUTHOR_(?:BYLINE|BIO)_(?:START|END) -->/gi, '');

const wordpressPublishDate = String(row.wordpress_publish_date || '').trim();
if (wordpressPublishDate) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(wordpressPublishDate)) throw new Error('The campaign topic WordPress publish date is invalid.');
  const parsedDate = new Date(wordpressPublishDate + 'T00:00:00Z');
  if (!Number.isFinite(parsedDate.getTime()) || parsedDate.toISOString().slice(0, 10) !== wordpressPublishDate) throw new Error('The campaign topic WordPress publish date is not a valid calendar date.');
  if (wordpressPublishDate > new Date().toISOString().slice(0, 10)) throw new Error('The WordPress publish date cannot be in the future.');
}


const title = String(metadata.h1 || '').trim() || String(publicationPackage.article_html).match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.[1]?.replace(/<[^>]+>/g, '').trim();
// A slug chosen for the campaign topic in the dashboard takes priority over the writer's recommendation.
const topicSlug = String(row.topic_wordpress_slug || '').trim().toLowerCase();
if (topicSlug && (topicSlug.length > 100 || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(topicSlug))) {
  throw new Error('The campaign topic WordPress URL slug must use only lowercase letters, numbers, and single hyphens.');
}
const articleSlugBase = topicSlug || String(metadata.slug || '').trim();
const articleIdSlug = String(row.article_id || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const articleSlugCollision = articleSlugBase.slice(0, 140) + '-article-' + articleIdSlug;
let slug = articleSlugBase;
const priorWordPressUrl = String(row.prior_wordpress_url || '').trim();
if (row.prior_wordpress_post_id && priorWordPressUrl) {
  try {
    const priorSlug = decodeURIComponent(new URL(priorWordPressUrl).pathname.split('/').filter(Boolean).at(-1) || '');
    if (/^[a-z0-9][a-z0-9-]*$/i.test(priorSlug)) slug = priorSlug;
  } catch { /* Keep the generated slug if the saved WordPress URL cannot be read. */ }
}
const excerpt = String(metadata.meta_description || '').trim();
if (!title || !slug || !excerpt) {
  throw new Error('The approved package is missing its title, slug, or meta description.');
}


return [{ json: {
  ...row,
  credential_name: config.credential_name,
  wordpress_api_url: publicationBaseUrl + '/wp-json/wp/v2',
  title, slug, article_slug_base: articleSlugBase, article_slug_collision: articleSlugCollision, excerpt, content: html,
  featured_image_source_url: featuredImageUrl,
  featured_image_alt_text: featuredImageAlt,
  wordpress_publish_date: wordpressPublishDate || null,
  wordpress_body: {
    title, content: html, slug, excerpt, status: 'publish',
    comment_status: 'closed', ping_status: 'closed', format: 'standard', ...(row.practice_id === 'practice_co_04' ? { categories: [16] } : {}),
    ...(wordpressPublishDate ? { date: wordpressPublishDate + 'T12:00:00' } : {})
  }
} }];

const context = $('Prepare WordPress Publication').first().json;
const posts = $input.all().map((item) => item.json).filter((post) => post?.id && post?.slug);
const priorPostId = String(context.prior_wordpress_post_id || '');
const priorPost = priorPostId ? posts.find((post) => String(post.id) === priorPostId) : null;
const articleSpecificPost = posts.find((post) => post.slug === context.article_slug_collision);
const baseSlugPost = posts.find((post) => post.slug === context.article_slug_base);
let slug = priorPost?.slug || context.slug;
// Once this article has a WordPress post, always update that exact post, even if its slug was changed in WordPress,
// so a re-send never creates a duplicate. The post's current slug (web address) is kept.
let existingPostId = priorPost?.id ? String(priorPost.id) : (/^\d+$/.test(priorPostId) ? priorPostId : null);
const keepExistingSlug = Boolean(existingPostId && !priorPost);
if (!existingPostId && articleSpecificPost) {
  slug = context.article_slug_collision;
  existingPostId = String(articleSpecificPost.id);
} else if (!existingPostId && baseSlugPost) {
  slug = context.article_slug_collision;
}
const wordpressBody = { ...context.wordpress_body, slug };
if (keepExistingSlug) delete wordpressBody.slug;
return [{ json: {
  ...context,
  slug,
  wordpress_body: wordpressBody,
  existing_post_id: existingPostId,
  // Lets the article banner keep the original date when an existing post is updated.
  existing_post_date: existingPostId ? String((priorPost || articleSpecificPost)?.date || '') || null : null,
  wordpress_publish_url: existingPostId
    ? context.wordpress_api_url + '/posts/' + existingPostId
    : context.wordpress_api_url + '/posts'
} }];

const response = $json;
const context = $('Choose WordPress Create or Update').first().json;
if (!response?.id || response?.status !== 'publish' || !response?.link || !response?.featured_media) {
  throw new Error('WordPress did not return a published post ID, featured image, and URL.');
}
return [{ json: {
  article_id: context.article_id,
  doctor_id: context.doctor_id,
  campaign_id: context.campaign_id,
  current_version: Number(context.current_version),
  publisher_config_reference: context.publisher_config_reference,
  external_post_id: String(response.id),
  featured_media_id: String(response.featured_media),
  published_url: String(response.link),
  wordpress_status: response.status,
  slug: response.slug || context.slug
} }];
